  "Hər şagirdin öz addımı var. Əsas odur ki, irəliləsin.": ["Every student has their own pace. What matters is moving forward.", "У каждого ученика свой шаг. Главное — двигаться вперёд."],
  "Hər gün bir az irəli – ilin sonunda böyük yol.": ["A little forward every day — a long way by the end of the year.", "Каждый день понемногу вперёд — к концу года большой путь."],
  "Səhv etmək öyrənməyin bir hissəsidir.": ["Making mistakes is part of learning.", "Ошибаться — часть учёбы."],
  "Bu gün həll etdiyin hər misal sabahkı imtahanda sənə kömək edəcək.": ["Every problem you solve today will help you in tomorrow's exam.", "Каждая решённая сегодня задача поможет тебе на завтрашнем экзамене."],
  "Diqqət + ardıcıllıq = uğur.": ["Attention + consistency = success.", "Внимание + постоянство = успех."],
  "Çətin sual – yeni bir şey öyrənmək fürsətidir.": ["A hard question is a chance to learn something new.", "Трудный вопрос — шанс узнать что-то новое."],
  "Özünü dünənki özünlə müqayisə et.": ["Compare yourself with who you were yesterday.", "Сравнивай себя с собой вчерашним."],
  "Kiçik addımlar da addımdır.": ["Small steps are steps too.", "Маленькие шаги — тоже шаги."],
  "Riyaziyyat səbir sevir: tələsmə, yoxla.": ["Maths loves patience: don't rush, check.", "Математика любит терпение: не спеши, проверяй."],
  "Sualı iki dəfə oxu – cavabın yarısı sualdadır.": ["Read the question twice — half the answer is in it.", "Прочитай вопрос дважды — половина ответа в нём."],
  "Bilik paylaşdıqca artır – yoldaşına kömək et.": ["Knowledge grows when shared — help a classmate.", "Знание растёт, когда им делишься — помоги товарищу."],
  "Bu gün 20 dəqiqə təkrar – sabah daha asan dərs.": ["20 minutes of review today — an easier lesson tomorrow.", "20 минут повторения сегодня — завтра урок легче."],
  "Uğur hər gün təkrarlanan kiçik səylərin cəmidir.": ["Success is the sum of small efforts repeated every day.", "Успех — это сумма маленьких ежедневных усилий."],
  "İnanırsansa, yarısını artıq etmisən.": ["If you believe, you're already halfway there.", "Если веришь — половина уже сделана."],
  "Dəftərin səliqəli olsa, fikrin də səliqəli olar.": ["A tidy notebook makes a tidy mind.", "Аккуратная тетрадь — аккуратные мысли."],
  "Hər test sənə nəyi bilmədiyini göstərir – bu da qazancdır.": ["Every test shows what you don't know yet — that's a gain too.", "Каждый тест показывает, чего ты ещё не знаешь, — это тоже польза."],
  "Sual vermək ayıb deyil, bilməmək qalmaq ayıbdır.": ["Asking is no shame; staying ignorant is.", "Спрашивать не стыдно — стыдно остаться незнающим."],
  "Başlamaq üçün mükəmməl olmaq lazım deyil, mükəmməl olmaq üçün başlamaq lazımdır.": ["You don't have to be perfect to start, but you have to start to become perfect.", "Не нужно быть совершенным, чтобы начать, — нужно начать, чтобы стать совершенным."],
  "Bugünkü zəhmət – sabahkı özgüvəndir.": ["Today's effort is tomorrow's confidence.", "Сегодняшний труд — завтрашняя уверенность."],
  "Yorulanda dayan, amma dayanıb qalma.": ["Rest when tired, but don't stay stopped.", "Устал — остановись, но не стой на месте."],
  "Hədəfini yaz, hər gün ona bax.": ["Write down your goal and look at it every day.", "Запиши свою цель и смотри на неё каждый день."],
