  "Suallar yalnız bu imtahana qədər keçilmiş mövzulardan seçilir (perspektiv plan). Sinifdə hər şagirdin sualları fərqlidir.": ["Questions come only from topics covered before this exam (long-term plan). Every student in the class gets different questions.", "Вопросы берутся только из тем, пройденных до этой работы (перспективный план). У каждого ученика класса свои вопросы."],
