  "{s} şagird × {n} sual = {need} sual lazımdır.": ["{s} students × {n} questions = {need} questions needed.", "{s} учеников × {n} вопросов = нужно {need} вопросов."],
  "Hovuz kifayətdir.": ["The pool is sufficient.", "Вопросов достаточно."],
