  "İki üzlü çap edin: hər şagirdə bir vərəq + cavab kartı.": ["Print double-sided: one sheet per student + answer card.", "Печатайте с двух сторон: один лист на ученика + бланк ответов."],
  "Variantlar hazır olanda.": ["When variants are ready.", "Когда варианты будут готовы."],
