  "Yazıdan sonra kartları skan edin – bal jurnala özü yazılır.": ["After the test, scan the cards — points go to the journal automatically.", "После работы отсканируйте бланки — баллы сами попадут в журнал."],
  // KSQ sual redaktəsi (13.10.2026)
  "Şagirdə toxunun – sualları görün, əvəz edin, düzəldin və ya ləğv edin.": ["Tap a student to see, replace, edit or annul questions.", "Нажмите на ученика — вопросы можно посмотреть, заменить, исправить или аннулировать."],
