  "ləğv edilib": ["annulled", "аннулирован"],
  "Bu şagirddə başqa sualla əvəz et (eyni mövzu, növ və çətinlik)": ["Replace for this student (same topic, type and difficulty)", "Заменить у этого ученика (та же тема, тип и сложность)"],
