  "Bankdakı səhv sual: bir daha heç bir varianta düşməsin və bu şagirddə əvəz olunsun": ["Wrong bank question: never use again and replace for this student", "Ошибочный вопрос банка: больше не использовать и заменить у этого ученика"],
  "Sual bankda gizlədildi və əvəz olundu": ["Question hidden in the bank and replaced", "Вопрос скрыт в банке и заменён"],
