  "Düzgün cavab (kart xanaları: rəqəm, - , / ;)": ["Correct answer (card boxes: digits, - , / ;)", "Правильный ответ (клетки бланка: цифры, - , / ;)"],
  "Eyni proqramlı siniflər – eyni ayarlarla birlikdə hazırla": ["Classes with the same programme — prepare together with the same settings", "Классы с той же программой — подготовить вместе с теми же настройками"],
  "nəticə yazılıb – dəyişmir": ["results recorded — not changed", "результаты внесены — не меняется"],
  "variantlar var – yenilənəcək": ["variants exist — will be recreated", "варианты есть — будут пересозданы"],
  "imtahan var": ["exam exists", "работа есть"],
  "imtahan yaradılacaq": ["exam will be created", "работа будет создана"],
  "Siniflər arasında suallar ən çox 20 % təkrarlanır.": ["Questions repeat across classes by at most 20 %.", "Между классами вопросы повторяются не более чем на 20 %."],
  "Süni intellekt bağlantısı yoxdur: kartlar oxunmağı gözləyəcək. Tənzimləmələr → «Süni intellekt» → Google Gemini (pulsuz açar: aistudio.google.com), OpenRouter və ya Anthropic açarını daxil edin.": ["No AI connection: cards will wait to be read. Settings → «AI» → enter a Google Gemini key (free key: aistudio.google.com), OpenRouter or Anthropic key.", "Нет подключения к ИИ: бланки будут ждать чтения. Настройки → «ИИ» → введите ключ Google Gemini (бесплатный ключ: aistudio.google.com), OpenRouter или Anthropic."],
  "Test layihələri": ["Test projects", "Проекты тестов"],
  "{n} fayl": ["{n} files", "файлов: {n}"],
  "Mövzuya uyğun testlər seçilmiş layihələrdən avtomatik götürülür; başqa layihəni qoşmaq üçün üzərinə toxunun.": ["Topic-matching tests are taken automatically from the selected projects; tap another project to connect it.", "Тесты по темам берутся автоматически из выбранных проектов; нажмите на другой проект, чтобы подключить его."],
  "Bu variantlar köhnə qaydalarla yaradılıb – mövzuya uyğun olmayan sual ola bilər. 1-ci addımda «Yenidən yarat» basın (nəticə yazılıbsa – sualları 2-ci addımda tək-tək əvəz edin).": ["These variants were created with the old rules — they may contain off-topic questions. Press «Recreate» in step 1 (if results are recorded, replace questions one by one in step 2).", "Эти варианты созданы по старым правилам — в них могут быть вопросы не по теме. Нажмите «Создать заново» в шаге 1 (если результаты внесены — заменяйте вопросы по одному в шаге 2)."],
  "Əvəz olundu: {n} sual ({s} şagird)": ["Replaced: {n} questions ({s} students)", "Заменено: {n} вопросов (учеников: {s})"],
  "Uyğunsuz sualları avtomatik düzəlt": ["Fix off-topic questions automatically", "Исправить неподходящие вопросы автоматически"],
  "Parametrli şablon suallar da (bank çatmayanda)": ["Also parametric template questions (when the bank runs short)", "Также параметрические шаблонные вопросы (если банка не хватает)"],
  "standart: yalnız layihə testləri (X–XI: P0010 Blok İmtahan)": ["default: project tests only (X–XI: P0010 Block Exam)", "по умолчанию: только тесты проекта (X–XI: P0010 Blok İmtahan)"],
  "Suallar yalnız layihənin testlərindən (X–XI: P0010 Blok İmtahan), şablon yoxdur. Təkrarı sistem özü ən az səviyyədə seçir.": ["Questions come only from the project's tests (X–XI: P0010 Block Exam), no templates. The system keeps repeats to the minimum itself.", "Вопросы только из тестов проекта (X–XI: P0010 Blok İmtahan), без шаблонов. Повторы система сама сводит к минимуму."],
  "Hər sual ən çox {k} şagirddə olacaq (bankda sual az olduğuna görə – ən az mümkün təkrar).": ["Each question will be given to at most {k} students (the bank is small — the minimum possible repeat).", "Каждый вопрос будет не более чем у {k} учеников (вопросов в банке мало — минимально возможный повтор)."],
  "Hər şagirdin sualları fərqlidir.": ["Every student has different questions.", "У каждого ученика свои вопросы."],
  "faylı qonşu mövzu ilə ortaqdır – sualları orada sayılır": ["file shared with a neighbouring topic — its questions are counted there", "файл общий с соседней темой — вопросы учтены там"],
  "Süni intellekt bu ay": ["AI this month", "ИИ в этом месяце"],
