  "Əvvəlcə sinif seçin": ["Choose a class first", "Сначала выберите класс"],
  "Bu məkanda heç bir sinif və ya qrupa qoşulmamısınız. Perspektiv plan qoşulduğunuz sinfə təyin olunur: Tənzimləmələr → Siniflər → sinfin kartında «Qoşul» – orada əsas proqramı da seçə bilərsiniz.": ["You have not joined any class or group in this workspace. A long-term plan is assigned to a class you join: Settings → Classes → «Join» on the class card – you can also choose the main program there.", "В этом пространстве вы не подключены ни к одному классу или группе. Перспективный план назначается классу, к которому вы подключены: Настройки → Классы → «Подключиться» на карточке класса – там же можно выбрать основную программу."],
