  "Geriləmə: {n} dərs": ["Behind: {n} lessons", "Отставание: {n} ур."],
  "X–XI sinifdə P0010, «Test toplusu» dərslərində P007 sualları; test dərs günü yaradılır, dərsin sonunda açılır, ertəsi gün 22:00 bağlanır, nəticə formativ jurnala": ["P0010 questions in grades X–XI, P007 in «Test toplusu» lessons; the test is created on the lesson day, opens at the end of the lesson, closes the next day at 22:00, the result goes to the formative journal", "Вопросы P0010 в X–XI классах, P007 на уроках «Test toplusu»; тест создаётся в день урока, открывается в конце урока, закрывается на следующий день в 22:00, результат – в формативный журнал"],
  "Avtomatik mövzu testi açıldı": ["Automatic topic test turned on", "Автоматический тест по теме включён"],
  "bu gün {n} test yaradıldı": ["{n} tests created today", "сегодня создано тестов: {n}"],
  "Avtomatik mövzu testi bağlandı": ["Automatic topic test turned off", "Автоматический тест по теме выключен"],
  "Hər dərsə avtomatik mövzu testi": ["Automatic topic test for every lesson", "Автотест по теме к каждому уроку"],
  "Bu sinif üçün plan yoxdur – yuxarıdakı «Proqramlar: seç / dəyiş» bölməsində «Əsas proqramı seç» düyməsi ilə kitabxanadan proqram seçin (Word planınızı Tənzimləmələr → Proqramlar → «Word planını yüklə» ilə əlavə edə bilərsiniz).": ["There is no plan for this class – choose a program from the library with «Choose main program» in «Programs: choose / change» above (you can add your Word plan via Settings → Programs → «Upload Word plan»).", "Для этого класса нет плана – выберите программу из библиотеки кнопкой «Выбрать основную программу» в разделе «Программы: выбрать / изменить» выше (свой план Word можно добавить: Настройки → Программы → «Загрузить план Word»)."],
  "İlin sonuna {n} dərs sığmır – geriləməni aradan qaldırmaq lazımdır.": ["{n} lessons do not fit before the end of the year – the delay needs to be caught up.", "До конца года не помещается уроков: {n} – нужно ликвидировать отставание."],
