  "Perspektiv plan proqramı sinfə bağlı deyil: hər sinif və qrup üçün səviyyəsinə uyğun proqramı özünüz seçirsiniz.": ["The long-term plan program is not tied to a class: for each class and group you choose the program that fits its level yourself.", "Программа перспективного плана не привязана к классу: для каждого класса и группы вы сами выбираете программу по уровню."],
  "Plan heç bir sinfə tətbiq olunmur – kitabxanada sabit proqram kimi qalır; sonra istənilən sinif və ya qrup üçün «Əsas proqram» və ya «Əlavə proqram» kimi seçirsiniz.": ["The plan is not applied to any class – it stays in the library as a fixed program; later you pick it for any class or group as the «Main program» or an «Extra program».", "План не применяется ни к одному классу – он остаётся в библиотеке как фиксированная программа; позже вы выбираете его для любого класса или группы как «Основную» или «Дополнительную программу»."],
  "Proqram kimi saxlanıldı": ["Saved as a program", "Сохранено как программа"],
  "Proqram seçmək üçün sinif və ya qrup seçin": ["Choose a class or group to pick a program", "Выберите класс или группу, чтобы выбрать программу"],
  "Proqram tətbiq olundu": ["Program applied", "Программа применена"],
  "Proqramlar kitabxanası": ["Program library", "Библиотека программ"],
