  "Qapalı": ["Closed", "Закрытые"],
  "Qoş": ["Attach", "Прикрепить"],
  "Qəbul (blok)": ["Admission (block)", "Приём (блок)"],
  "Repetitor/hazırlıq kursu: KSQ, BSQ və yarımil yoxdur. Mövzular qrupun kurs müddətinə və dərs vaxtlarına bərabər paylanır, hər mövzunun son dərsi – test; istəsəniz bölmə sonunda və müəyyən aralıqla sınaq, sonda yekun sınaq.": ["Tutoring/preparation course: no KSQ, BSQ or semesters. Topics are spread evenly over the group's course length and lesson times; the last lesson of each topic is a test; optionally a mock exam at the end of a section and at set intervals, and a final mock exam at the end.", "Репетиторский/подготовительный курс: нет КСО, БСО и полугодий. Темы равномерно распределяются по длительности курса и времени занятий группы; последний урок каждой темы – тест; по желанию пробный экзамен в конце раздела и с заданным интервалом, итоговый – в конце."],
  "Saxla": ["Save", "Сохранить"],
  "Saxlanıldı": ["Saved", "Сохранено"],
  "Seç": ["Choose", "Выбрать"],
  "Seçilib": ["Chosen", "Выбрано"],
  "Seçilməyib – jurnal və tarixlər əsas proqrama görə gedir.": ["Not chosen – the journal and dates follow the main program.", "Не выбрана – журнал и даты идут по основной программе."],
  "Sinif dərsinə dəstək": ["Support for classroom lessons", "Поддержка уроков в классе"],
  "Sinif rəqəmi müəyyən deyil – uyğun proqramlar öndə çıxmır. Sinif formasında «Sinif rəqəmi»ni seçin.": ["The grade number is not set – matching programs are not shown first. Choose the «Grade number» in the class form.", "Номер класса не указан – подходящие программы не выводятся первыми. Выберите «Номер класса» в форме класса."],
  "Siyahını aç": ["Open list", "Открыть список"],
