  "Səviyyə": ["Level", "Уровень"],
  "Tapş.": ["Tasks", "Задач"],
  "Tənzimləmələr → Siniflər": ["Settings → Classes", "Настройки → Классы"],
  "Təsvir": ["Description", "Описание"],
  "Tətbiq et": ["Apply", "Применить"],
  "Tətbiq olunanda: hazırkı plan kitabxanada «əvvəlki plan» kimi qalır (geri qaytarmaq olar); jurnalda yazılmış dərslərin mövzusu dəyişmir; yeni dərslər sinfin cədvəlinə görə tarixlənir. Proqram başqa proqramla qarışdırılmır.": ["When applied: the current plan stays in the library as the «previous plan» (can be restored); topics of lessons already written in the journal do not change; new lessons are dated by the class schedule. Programs are not mixed with each other.", "При применении: текущий план остаётся в библиотеке как «предыдущий план» (можно вернуть); темы уже записанных в журнале уроков не меняются; новые уроки датируются по расписанию класса. Программы не смешиваются."],
