  "«# » ilə başlayan sətir – bölmə; qalan hər sətir – bir mövzu (nömrə və «-» atılır)": ["a line starting with «# » is a section; every other line is a topic (numbers and «-» are dropped)", "строка, начинающаяся с «# » – раздел; остальные строки – по одной теме (номера и «-» отбрасываются)"],
  "«Qoşul»": ["«Join»", "«Присоединиться»"],
