  "Əlavə proqram jurnala yazılmır və əsas proqramla qarışmır – bütün sinif və ya səviyyə qrupu üçün ayrıca dərs siyahısıdır.": ["An extra program is not written to the journal and does not mix with the main program – it is a separate lesson list for the whole class or a level group.", "Дополнительная программа не записывается в журнал и не смешивается с основной – это отдельный список уроков для всего класса или группы уровня."],
  "Əlavə proqram jurnala yazılmır və əsas proqramla qarışmır – öz dərs siyahısı sinfin cədvəlinə görə ayrıca göstərilir və çap olunur.": ["An extra program is not written to the journal and does not mix with the main program – its own lesson list is shown and printed separately by the class schedule.", "Дополнительная программа не записывается в журнал и не смешивается с основной – её список уроков показывается и печатается отдельно по расписанию класса."],
