  "Şagird linki açır, soyadını, adını, ata adını və doğum tarixini yazır – giriş kodu və PIN avtomatik verilir. Təkrar qeydiyyat bloklanır.": ["The student opens the link and enters surname, first name, patronymic and date of birth – the login code and PIN are issued automatically. Repeat registration is blocked.", "Ученик открывает ссылку и вводит фамилию, имя, отчество и дату рождения – код входа и PIN выдаются автоматически. Повторная регистрация блокируется."],
