  "Siz": ["You", "Вы"],
  "paralel:": ["parallel:", "параллельно:"],
  "Saxlanan qeydin əsas sinfi və ID-si qalır; o biri qeydin qiymətləri, testləri, davamiyyəti ona keçir, sinfi isə əlavə sinif olur (məs. IX + XI). Silinən qeyd arxivə gedir, onun ID-si ilə giriş bağlanır. Geri qaytarılmır – adı yazmaqla təsdiq olunur.": ["The kept record keeps its main class and ID; the other record's grades, tests and attendance move to it, and its class becomes an extra class (e.g. IX + XI). The deleted record goes to the archive and its ID login is closed. This cannot be undone – confirm by typing the name.", "У сохраняемой записи остаётся основной класс и ID; оценки, тесты и посещаемость второй записи переходят к ней, а её класс становится дополнительным (напр. IX + XI). Удаляемая запись уходит в архив, вход по её ID закрывается. Отменить нельзя – подтверждается вводом имени."],
  "Şagird öz əsas sinfində qalır və bu qrupda da olur (jurnal, testlər, sınaqlar). Məs.: fərdi hazırlıqda IX və XI sinif – bir şagird, iki sinif.": ["The student stays in their main class and is also in this group (journal, tests, mock exams). E.g. in private tutoring a grade IX and XI class – one student, two classes.", "Ученик остаётся в своём основном классе и состоит также в этой группе (журнал, тесты, пробные экзамены). Напр. в индивидуальной подготовке IX и XI классы – один ученик, два класса."],
  "Şagird öz əsas sinfində qalır və bu sinifdə də olur (jurnal, testlər, sınaqlar). Məs.: fərdi hazırlıqda IX və XI sinif – bir şagird, iki sinif.": ["The student stays in their main class and is also in this class (journal, tests, mock exams). E.g. in private tutoring a grade IX and XI class – one student, two classes.", "Ученик остаётся в своём основном классе и состоит также в этом классе (журнал, тесты, пробные экзамены). Напр. в индивидуальной подготовке IX и XI классы – один ученик, два класса."],
