  "Bu qrupda KSQ/BSQ keçirilmir – bütöv sinifdə keçirilir.": ["KSQ/BSQ are not held in this group – they are held with the whole class.", "В этой группе КСО/БСО не проводятся – они проводятся для всего класса."],
