  "{delay_days} gün gec": ["{delay_days} days late", "на {delay_days} дн. позже"],
  "{x1} gün tez": ["{x1} days early", "на {x1} дн. раньше"],
  "Qeyd:": ["Note:", "Заметка:"],
  "✓ Keçildi": ["✓ Done", "✓ Пройдено"],
  "«Təkrar» – mövzu sayılır və gündəlik plan (AI) növbəti dərslərin əvvəlinə qısa təkrar qoyur. «Qismən» – sayılmır, davam edəcək.": ["«Review» – the topic counts and the daily plan (AI) adds a short review at the start of the next lessons. «Partially» – does not count, it will continue.", "«Повторить» – тема засчитывается, а ежедневный план (ИИ) добавит краткое повторение в начало следующих уроков. «Частично» – не засчитывается, тема будет продолжена."],
  "Rəsmi tarix:": ["Official date:", "Официальная дата:"],
  "jurnalda: {x1}": ["in the journal: {x1}", "в журнале: {x1}"],
  "Qeydi götür": ["Remove the mark", "Убрать отметку"],
  "Toplu qeyd – keçilmiş mövzular": ["Bulk mark – completed topics", "Массовая отметка – пройденные темы"],
  "Keçildi kimi qeyd et": ["Mark as done", "Отметить как пройденные"],
  "Tətbiqə gec başlamısınızsa, artıq keçdiyiniz mövzuları bir dəfəyə qeyd edin. Artıq keçilmiş kimi görünənlər dəyişmir.": ["If you started using the app late, mark the topics you have already covered all at once. Topics already shown as done are not changed.", "Если вы начали пользоваться приложением позже, отметьте уже пройденные темы за один раз. Уже отмеченные как пройденные не изменяются."],
  "№ (başlanğıc)": ["№ (start)", "№ (начало)"],
  "№ (son)": ["№ (end)", "№ (конец)"],
  "… və daha": ["… and", "… и ещё"],
  "Rəsmi plan": ["Official plan", "Официальный план"],
  "Keçilən": ["Completed", "Пройдено"],
  "Plan və faktiki keçilən mövzular, həftələr üzrə": ["Planned and actually covered topics, by week", "Запланированные и фактически пройденные темы по неделям"],
  ": plan": [": plan", ": план"],
  "· keçilən": ["· covered", "· пройдено"],
