  "DİM 9": ["DİM 9", "ГЭЦ 9"],
  "test bazasında bu mövzuya uyğun fayl tapılmadı – aşağıdan əl ilə seçin.": ["no file matching this topic was found in the test bank – choose manually below.", "в банке тестов не найден файл по этой теме – выберите вручную ниже."],
  "Avtomatik əlavə olundu:": ["Added automatically:", "Добавлено автоматически:"],
  "sual). Lazım olmayanları siyahıdan silin.": ["questions). Remove those you do not need from the list.", "вопросов). Ненужные удалите из списка."],
  "Bir fayldan ən çoxu": ["At most from one file", "Из одного файла не более"],
  "sual (çoxdursa təsadüfi, qapalı : açıq ≈ 2 : 1)": ["questions (random if more, closed : open ≈ 2 : 1)", "вопросов (если больше – случайно, закрытые : открытые ≈ 2 : 1)"],
  "Variant:": ["Variant:", "Вариант:"],
  "«{vk}» variantının sualları": ["Questions of the «{vk}» variant", "Вопросы варианта «{vk}»"],
  "Seçilmiş suallar": ["Selected questions", "Выбранные вопросы"],
  "Yuxarıdan test bazasından seçin və ya öz sualınızı yazın.": ["Choose from the test bank above or write your own question.", "Выберите из банка тестов выше или напишите свой вопрос."],
  "öz sualım": ["my own question", "мой вопрос"],
  "Sınaq bütün siniflərdən birdəfəlik silinir – nəticələr və şagird cəhdləri də (geri qaytarmaq olmur).": ["The mock exam is deleted from all classes permanently – results and student attempts too (cannot be undone).", "Пробный экзамен безвозвратно удаляется из всех классов – результаты и попытки учеников тоже (вернуть нельзя)."],
  "Sınaq sinfinizdən birdəfəlik silinir – nəticələr və şagird cəhdləri də (geri qaytarmaq olmur).": ["The mock exam is deleted from your class permanently – results and student attempts too (cannot be undone).", "Пробный экзамен безвозвратно удаляется из вашего класса – результаты и попытки учеников тоже (вернуть нельзя)."],
  "Hər şagird öz səviyyəsinin variantını alır (Jurnal → Səviyyə qrupları). Səviyyəsi təyin edilməyən və ya variantı boş qalan qrupun şagirdləri «Orta» variantını alır. Qiymət hər şagirdin öz variantının sual sayından hesablanır. Şagird səviyyə adını görmür.": ["Each student gets the variant for their level (Journal → Level groups). Students in a group with no level or an empty variant get the «Average» variant. The grade is calculated from the number of questions in each student's own variant. Students do not see the level name.", "Каждый ученик получает вариант своего уровня (Журнал → Группы по уровню). Ученики группы без уровня или с пустым вариантом получают вариант «Средний». Оценка считается по числу вопросов в варианте самого ученика. Ученик не видит название уровня."],
  "təkrar cəhd": ["repeat attempt", "повторная попытка"],
  "sonradan yazıb": ["wrote later", "написал(а) позже"],
  "{length} sual götürüldü": ["{length} questions taken", "Взято вопросов: {length}"],
  "Dərs cədvəli": ["Lesson timetable", "Расписание уроков"],
  "Bütün siniflər (admin baxışı)": ["All classes (admin view)", "Все классы (режим администратора)"],
  "Siz heç bir sinfin rəhbəri deyilsiniz. Tənzimləmələr → Siniflər → sinfi açın → «Mən sinif rəhbəriyəm» (və ya admin təyin edir).": ["You are not the homeroom teacher of any class. Settings → Classes → open the class → «I am the homeroom teacher» (or an admin assigns it).", "Вы не являетесь классным руководителем ни одного класса. Настройки → Классы → откройте класс → «Я классный руководитель» (или назначает админ)."],
  "— Sinif seçin —": ["— Select a class —", "— Выберите класс —"],
  "rəhbər yoxdur": ["no homeroom teacher", "классного руководителя нет"],
  "Dövr üzrə (seçilmiş yarımil)": ["For the period (selected semester)", "За период (выбранное полугодие)"],
  "fənn": ["subjects", "предметов"],
  "saat həftədə": ["hours per week", "часов в неделю"],
  "dərs yazılıb": ["lessons written", "уроков записано"],
  "Bu gün dərsdə yoxdur:": ["Not in class today:", "Сегодня отсутствуют на уроках:"],
  "%+ buraxma:": ["%+ absences:", "%+ пропусков:"],
