  "Keyfiyyət": ["Quality", "Качество"],
  "SOU": ["SOU", "СОУ"],
  "Qiymətsiz": ["Ungraded", "Без оценок"],
  "Bu sinfə hələ heç bir müəllim qoşulmayıb.": ["No teacher has joined this class yet.", "К этому классу пока не присоединился ни один учитель."],
  "Hər fənn üzrə: həftəlik saat, perspektiv plandakı dərs sayı, cədvələ görə dövrdəki dərs saatları, bu günə (": ["For each subject: weekly hours, number of lessons in the long-term plan, lesson hours in the period per timetable, lessons due by today (", "По каждому предмету: часы в неделю, число уроков в перспективном плане, учебные часы за период по расписанию, должно быть пройдено на сегодня ("],
  ") qədər keçilməli olanlar, jurnalda yazılanlar, yazılmayanlar, plan üzrə keçilən və qalan mövzular, geriləmə.": ["), written in the journal, not written, topics covered and remaining per plan, lag.", "), записано в журнале, не записано, пройденные и оставшиеся темы по плану, отставание."],
  "Fənn qiyməti: yarımil qiyməti (KSQ×0,4 + BSQ×0,6), hələ yoxdursa formativ qiymətlərin ortası. Əlaçı – hamısı «5»; zərbəçi – «4» və «5»; bir «3»-lü – yalnız bir «3»; geridə qalan – ən azı bir «2». Boş xana – şagird həmin qrupda deyil.": ["Subject grade: the semester grade (KSQ×0.4 + BSQ×0.6), or the formative average if there is none yet. Excellent – all «5»; good – «4» and «5»; one «3» – exactly one «3»; lagging – at least one «2». Empty cell – the student is not in that group.", "Оценка по предмету: полугодовая (КСО×0,4 + БСО×0,6), а если её ещё нет – среднее формативных. Отличник – все «5»; хорошист – «4» и «5»; один «3» – ровно одна «3»; отстающий – хотя бы одна «2». Пустая ячейка – ученик не входит в эту группу."],
  "Üzrsüz": ["Unexcused", "Без уважительной причины"],
  "Üzrlü": ["Excused", "По уважительной причине"],
  "Gecikib": ["Late", "Опоздал(а)"],
