  "· şagird:": ["· student:", "· ученик:"],
  "valideyn məlumatı yoxdur": ["no parent information", "данных о родителях нет"],
  "Şagird və valideyn telefonlarını yalnız sinif rəhbəri və admin görür. Nömrə istənilən yazılışda daxil edilə bilər (050 123 45 67) – avtomatik +994 50 123 45 67 formatına salınır.": ["Only the homeroom teacher and admin see student and parent phone numbers. A number can be entered in any format (050 123 45 67) – it is converted automatically to +994 50 123 45 67.", "Телефоны учеников и родителей видят только классный руководитель и админ. Номер можно вводить в любом формате (050 123 45 67) – он автоматически приводится к виду +994 50 123 45 67."],
  "Telefonlar yadda saxlanıldı": ["Phone numbers saved", "Телефоны сохранены"],
