  "Sütunlar:": ["Columns:", "Столбцы:"],
  ", Şagirdin telefonu, Ana, Ana telefonu, Ata, Ata telefonu (ardıcıllıq vacib deyil). Şagird adı sinif siyahısı ilə eşləşdirilir («oğlu/qızı» yazılmaya bilər). Boş xana mövcud nömrəni silmir.": [", Student's phone, Mother, Mother's phone, Father, Father's phone (order does not matter). The student name is matched with the class list («son of/daughter of» may be omitted). An empty cell does not delete an existing number.", ", Телефон ученика, Мать, Телефон матери, Отец, Телефон отца (порядок не важен). Имя ученика сопоставляется со списком класса («сын/дочь» можно не писать). Пустая ячейка не удаляет существующий номер."],
