  "A4, ağ-qara (Canon üçün) · altbilgidə tarix və səhifə nömrəsi · sinif rəhbəri və direktor müavininin imza yeri. Qruplar (bölünmə və tədris) fənn sətirlərində göstərilir.": ["A4, black and white (for Canon) · date and page number in the footer · signature place for the homeroom teacher and deputy principal. Groups (split and teaching) are shown in the subject rows.", "A4, чёрно-белый (для Canon) · в нижнем колонтитуле дата и номер страницы · место для подписи классного руководителя и завуча. Группы (деления и учебные) показаны в строках предметов."],
