  "Hələ sorğu yoxdur. «Yeni sorğu» ilə hazır peşəkar şablondan (33 sual, 8 meyar) başlayın.": ["No surveys yet. Start from the ready professional template (33 questions, 8 criteria) with «New survey».", "Опросов пока нет. Начните с готового профессионального шаблона (33 вопроса, 8 критериев) кнопкой «Новый опрос»."],
