  "Şagirdə müraciət (giriş mətni)": ["Message to the student (intro text)", "Обращение к ученику (вводный текст)"],
  "Şagird hər tədris həftəsində bir dəfə cavab verir; nəticələr həftələr üzrə müqayisə olunur.": ["A student answers once each school week; results are compared week by week.", "Ученик отвечает один раз в учебную неделю; результаты сравниваются по неделям."],
  "Hər şagird bir dəfə cavab verir.": ["Each student answers once.", "Каждый ученик отвечает один раз."],
  "Hər həftə": ["Every week", "Каждую неделю"],
  "Qısa həftəlik sorğu – hər həftə ~8 sual (1–2 dəq.), suallar növbə ilə dəyişir; 4–5 həftədə bütün anket əhatə olunur (tövsiyə)": ["Short weekly survey – ~8 questions each week (1–2 min), questions rotate; the whole questionnaire is covered in 4–5 weeks (recommended)", "Короткий еженедельный опрос – ~8 вопросов в неделю (1–2 мин), вопросы чередуются; вся анкета охватывается за 4–5 недель (рекомендуется)"],
  "Şagirdlərimin tətbiqində də göstər (siniflərim)": ["Also show in my students' app (my classes)", "Показывать также в приложении моих учеников (мои классы)"],
  "«Özünüz haqqında» bölməsi (sinif, davamiyyət – istəyə görə)": ["«About yourself» section (class, attendance – optional)", "Раздел «О себе» (класс, посещаемость – по желанию)"],
  "Suallar əvvəlki sorğudan köçürülür – nəticələr dalğalar üzrə müqayisə olunacaq.": ["Questions are copied from the previous survey – results will be compared across waves.", "Вопросы копируются из предыдущего опроса – результаты будут сравниваться по волнам."],
  "Şablon: fənn bilgisi və izah, dərsin təşkili, qiymətləndirmə, ünsiyyət, motivasiya, intizam (28 sual, şkala 1–5), ümumi bal, tövsiyə (NPS), 3 açıq sual. Açmazdan əvvəl sualları dəyişə bilərsiniz.": ["Template: subject knowledge and explanation, lesson organization, assessment, communication, motivation, discipline (28 questions, scale 1–5), overall score, recommendation (NPS), 3 open questions. You can change the questions before opening.", "Шаблон: знание предмета и объяснение, организация урока, оценивание, общение, мотивация, дисциплина (28 вопросов, шкала 1–5), общий балл, рекомендация (NPS), 3 открытых вопроса. Вопросы можно изменить до открытия."],
