  "tarixində açılacaq – o vaxta qədər link «açılacaq» yazacaq.": ["will open on this date – until then the link shows «will open».", "откроется в эту дату – до этого ссылка будет показывать «откроется»."],
  "hələ açılmayıb": ["not open yet", "ещё не открыт"],
  "– şagirdlər linkdə cavab verə bilməz. Linki göndərəndə sorğu avtomatik açılacaq.": ["– students cannot answer via the link. The survey will open automatically when you send the link.", "– ученики не могут отвечать по ссылке. Опрос откроется автоматически, когда вы отправите ссылку."],
