  "+ Ümumi link (WhatsApp qrupu üçün)": ["+ General link (for a WhatsApp group)", "+ Общая ссылка (для группы WhatsApp)"],
  "– bütün suallar (7–10 dəq.).": ["– all questions (7–10 min).", "– все вопросы (7–10 мин)."],
