  "hər həftə suallar dəyişir": ["questions change every week", "вопросы меняются каждую неделю"],
  "hər şagird başqa dəst alır, birlikdə bütün anket əhatə olunur": ["each student gets a different set, together covering the whole questionnaire", "каждый ученик получает свой набор, вместе охватывается вся анкета"],
  ". Eyni sorğu üçün WhatsApp qrupuna həm tam, həm qısa link göndərə bilərsiniz. Sinif linki ilə nəticələr siniflər üzrə müqayisə olunur (hər sinifdə ≥": [". For the same survey you can send both the full and the short link to a WhatsApp group. With a class link results are compared by class (in each class ≥", ". Для одного опроса в группу WhatsApp можно отправить и полную, и короткую ссылку. По ссылке класса результаты сравниваются по классам (в каждом классе ≥"],
  "cavab).": ["answers).", "ответов)."],
  "Şagirdin tətbiqində": ["In the student's app", "В приложении ученика"],
  "Sorğu açıq olduqca dərs dediyiniz siniflərin şagirdləri onu tətbiqdə": ["While the survey is open, students of the classes you teach see it in the app, in the", "Пока опрос открыт, ученики ваших классов видят его в приложении в разделе"],
  "«Sorğular»": ["«Surveys»", "«Опросы»"],
  "bölməsində və «Bu gün» səhifəsində görür.": ["section and on the «Today» page.", "и на странице «Сегодня»."],
  "Hər yeni tədris həftəsində (bazar ertəsi) sorğu yenidən açılır.": ["The survey reopens at the start of each new school week (Monday).", "Опрос открывается заново в начале каждой учебной недели (в понедельник)."],
  "Tətbiqdən gələn cavablar sinif linkinə yazılır.": ["Answers from the app are recorded under the class link.", "Ответы из приложения записываются в ссылку класса."],
  "Söndürülüb – yalnız link ilə. «Parametrlər»dən aça bilərsiniz.": ["Turned off – link only. You can turn it on in «Settings».", "Отключено – только по ссылке. Включить можно в «Параметрах»."],
  "Anonimlik": ["Anonymity", "Анонимность"],
  "Cavabda şagirdin adı, hesabı, IP və cihazı saxlanmır.": ["The student's name, account, IP and device are not stored with the answer.", "Имя, аккаунт, IP и устройство ученика вместе с ответом не сохраняются."],
  "Təkrar göndərmə yalnız ayrıca saxlanan şifrəli nişanla yoxlanır.": ["Repeat submissions are checked only with a separately stored encrypted token.", "Повторная отправка проверяется только по отдельно хранимому зашифрованному маркеру."],
  "Nəticə yalnız ən azı": ["The result is visible only with at least", "Результат виден только при наличии не менее"],
