  "Anonimlik həddi": ["Anonymity threshold", "Порог анонимности"],
  "Qısa həftəlik sorğu (hər həftə ~8 sual, növbə ilə)": ["Short weekly survey (~8 questions each week, rotating)", "Короткий еженедельный опрос (~8 вопросов в неделю, по очереди)"],
  "Şagirdlərimin tətbiqində göstər": ["Show in my students' app", "Показывать в приложении моих учеников"],
  "Yeni bölmə": ["New section", "Новый раздел"],
  "Sorğuya artıq cavab verilib – suallar dəyişdirilə bilməz (nəticələr müqayisəli qalsın). Dəyişiklik üçün «Yenidən keçir» ilə yeni dalğa yaradın.": ["The survey already has answers – questions cannot be changed (so results stay comparable). To make changes, create a new wave with «Run again».", "На опрос уже есть ответы – вопросы менять нельзя (чтобы результаты оставались сопоставимыми). Для изменений создайте новую волну кнопкой «Провести заново»."],
