  "Cavablar qarışıq sıra ilə və tarixsiz göstərilir. «Gizlət» – təhqiramiz cavabı hesabatdan çıxarır (silinmir).": ["Answers are shown in mixed order and without dates. «Hide» removes an offensive answer from the report (it is not deleted).", "Ответы показываются вперемешку и без дат. «Скрыть» убирает оскорбительный ответ из отчёта (не удаляя)."],
