  "cavabda sinif göstərilməyib (sinif seçimindən əvvəl gələn cavablar) – ümumi nəticəyə daxildir.": ["answers have no class (answers from before class selection) – included in the overall result.", "ответов без указания класса (поступили до выбора класса) – входят в общий результат."],
  "Süni intellektin rəyi": ["AI feedback", "Отзыв ИИ"],
  "{clsName} sinfi üçün təlim strategiyası": ["Teaching strategy for class {clsName}", "Стратегия обучения для класса {clsName}"],
  "peşəkar inkişaf üçün": ["for professional development", "для профессионального развития"],
  "Rəy hazırla": ["Generate feedback", "Подготовить отзыв"],
  "Meyarların rəqəmləri və açıq cavablar əsasında xülasə, güclü tərəflər, inkişaf zonaları, açıq cavabların mövzuları və ölçülə bilən tövsiyələr. Provayderə yalnız ümumi rəqəmlər və anonim mətnlər gedir. Tənzimləmələr → «Süni intellekt»də öz açarınız lazımdır.": ["A summary, strengths, development areas, open-answer themes and measurable recommendations based on the criteria figures and open answers. Only overall figures and anonymous texts are sent to the provider. You need your own key in Settings → «Artificial intelligence».", "Сводка, сильные стороны, зоны развития, темы открытых ответов и измеримые рекомендации на основе цифр по критериям и открытых ответов. Провайдеру отправляются только общие цифры и анонимные тексты. Нужен свой ключ в Настройки → «Искусственный интеллект»."],
  "Açıq cavabların mövzuları": ["Themes of open answers", "Темы открытых ответов"],
  "Tövsiyələr": ["Recommendations", "Рекомендации"],
  "Ölçü:": ["Measure:", "Мера:"],
  "Diqqət": ["Attention", "Внимание"],
  "cavab · rəy köməkçidir – müəllim tərəfindən yoxlanmalıdır.": ["answers · the feedback is an aid – the teacher must verify it.", "ответов · отзыв является помощником – учитель должен его проверить."],
  "rəhbər:": ["homeroom teacher:", "руководитель:"],
  "{x1} plan hazırlandı, {failed} alınmadı": ["{x1} plans prepared, {failed} failed", "Планов подготовлено: {x1}, не получилось: {failed}"],
  "Planlar hazırdır": ["The plans are ready", "Планы готовы"],
  "Gündəlik planlaşdırma": ["Daily planning", "Ежедневное планирование"],
  "Dərs həftəsi": ["School week", "Учебная неделя"],
  "Planı süni intellekt doldurur – bunun üçün öz API açarınızı (Gemini, OpenRouter və s.) bir dəfə daxil edin. Açarsız da hər dərsin şablonuna baxmaq, çap etmək və Word-ə yükləmək olar.": ["AI fills in the plan – for this enter your own API key (Gemini, OpenRouter, etc.) once. Even without a key you can view each lesson's template, print it and download it to Word.", "План заполняет искусственный интеллект – для этого один раз введите свой API-ключ (Gemini, OpenRouter и др.). Без ключа тоже можно просматривать шаблон каждого урока, печатать и скачивать в Word."],
  "Açarı qoş": ["Add the key", "Добавить ключ"],
