  ". Hazır plan silinmədən yenisi hazırlanmır.": [". A new plan is not prepared until the ready plan is deleted.", ". Новый план не готовится, пока готовый не удалён."],
  "Planlar bir-bir hazırlanır (hər biri 20–60 saniyə). Səhifəni bağlamayın.": ["Plans are prepared one by one (20–60 seconds each). Do not close the page.", "Планы готовятся по одному (по 20–60 секунд). Не закрывайте страницу."],
  "Alınmayan: {failed}": ["Failed: {failed}", "Не получилось: {failed}"],
