  "-ci saat · perspektiv plan №": ["period · long-term plan №", "-й урок · перспективный план №"],
  "Əlavə istək (istəyə görə)": ["Additional request (optional)", "Дополнительная просьба (по желанию)"],
  "Mövzu, altstandart kodları, test toplusunun səhifəsi, sinif və ev tapşırıqlarının nömrələri perspektiv plandan olduğu kimi götürülür. Plan ARTİ-nin «Gündəlik planlaşdırma» formasında, sizin API açarınızla hazırlanır.": ["The topic, sub-standard codes, the test collection page and the class and homework task numbers are taken from the long-term plan as they are. The plan is prepared in the ARTİ «Daily planning» form with your API key.", "Тема, коды подстандартов, страница сборника тестов и номера классных и домашних заданий берутся из перспективного плана как есть. План готовится в форме ARTİ «Ежедневное планирование» с вашим API-ключом."],
  "Promtu gizlət": ["Hide the prompt", "Скрыть промпт"],
  "Göndəriləcək promta bax": ["View the prompt to be sent", "Посмотреть отправляемый промпт"],
  "Plan silinsin? Sonra yenisini hazırlamaq olar.": ["Delete the plan? You can prepare a new one afterwards.", "Удалить план? Потом можно подготовить новый."],
  "Xeyr": ["No", "Нет"],
  "Əl ilə doldur": ["Fill in manually", "Заполнить вручную"],
  "Süni intellektlə hazırla": ["Prepare with AI", "Подготовить с ИИ"],
  "Plan hələ hazırlanmayıb – aşağıda perspektiv plandan doldurulmuş şablon var (mövzu, altstandart, meyar, ev tapşırığı). «Əl ilə doldur» ilə hər sətri özünüz yazın": ["The plan has not been prepared yet – below is a template filled from the long-term plan (topic, sub-standard, criterion, homework). Write each line yourself with «Fill in manually»", "План ещё не подготовлен – ниже шаблон, заполненный из перспективного плана (тема, подстандарт, критерий, домашнее задание). Через «Заполнить вручную» напишите каждую строку сами"],
  "«Süni intellektlə hazırla» ilə tam planı hazırlayın": ["prepare the full plan with «Prepare with AI»", "подготовьте полный план через «Подготовить с ИИ»"],
