  "Əməliyyat": ["Action", "Действие"],
  "Obyekt": ["Object", "Объект"],
  "Başqa məktəbə köçdü": ["Moved to another school", "Перешёл в другую школу"],
  "Başqa şəhərə / rayona köçdü": ["Moved to another city / district", "Переехал в другой город / район"],
  "Xaricə getdi": ["Moved abroad", "Уехал за границу"],
