  "Səhv əlavə olunub": ["Added by mistake", "Добавлен по ошибке"],
  "+ Yeni sinif / qrup": ["+ New class / group", "+ Новый класс / группа"],
  "Sinif məktəbə aiddir: başqa müəllim yaradıbsa, yenisini yaratmayın – «Qoşul» düyməsini basın.": ["A class belongs to the school: if another teacher has created it, do not create a new one – press «Join».", "Класс принадлежит школе: если его создал другой учитель, не создавайте новый – нажмите «Присоединиться»."],
  "müəllim yoxdur": ["no teacher", "учителя нет"],
  "Sinif rəhbəri:": ["Homeroom teacher:", "Классный руководитель:"],
  "qoşulmamısınız": ["you have not joined", "вы не присоединились"],
  "Bölünmə / şagird": ["Split / students", "Деление / ученики"],
  "Üzvlər": ["Members", "Участники"],
  "Bölünmə yarat": ["Create a split", "Создать деление"],
  "Hələ sinif yoxdur.": ["There are no classes yet.", "Классов пока нет."],
  "Rəsmi perspektiv planları yüklə (hamısı birlikdə)": ["Upload the official long-term plans (all together)", "Загрузить официальные перспективные планы (все вместе)"],
  "Word (.docx) fayllarını seçin – fayl adına görə sinfə özü bağlanır (məs. «X-e sinif – Riyaziyyat perspektiv plan…» → X e). Jurnal qeydləri qorunur.": ["Choose Word (.docx) files – each is attached to the class by its file name (e.g. «X-e sinif – Riyaziyyat perspektiv plan…» → X e). Journal entries are kept.", "Выберите файлы Word (.docx) – каждый привязывается к классу по имени файла (напр. «X-e sinif – Riyaziyyat perspektiv plan…» → X e). Записи журнала сохраняются."],
  "{length} plan yükləndi": ["{length} plans uploaded", "Загружено планов: {length}"],
  "Yüklə (": ["Upload (", "Загрузить ("],
  "dərs · KSQ": ["lessons · KSQ", "уроков · КСО"],
  "· BSQ": ["· BSQ", "· БСО"],
  "Fərdi sinif yaradıldı – fərdi məkana keçilir": ["The private class was created – switching to the private workspace", "Личный класс создан – переход в личное пространство"],
  "{name} – redaktə": ["{name} – edit", "{name} – изменение"],
  "Yeni sinif / qrup": ["New class / group", "Новый класс / группа"],
  "Harada": ["Where", "Где"],
  "Fərdi (hazırlıq / repetitor) – məktəbə aid deyil": ["Private (preparation / tutor) – not part of the school", "Личное (подготовка / репетитор) – не относится к школе"],
  "Fərdi sinif məktəbin hesabatlarına, siyahılarına və adminə düşmür; yalnız siz görürsünüz. Yuxarıdakı «Məktəb · Fərdi» düyməsi ilə məkanlar arasında keçirsiniz.": ["A private class does not appear in the school's reports, lists or to the admin; only you see it. Switch between workspaces with the «School · Private» button above.", "Личный класс не попадает в отчёты и списки школы и к админу; его видите только вы. Между пространствами переключайтесь кнопкой «Школа · Личное» выше."],
  "məs. X b (riyaziyyat qrupu), Olimpiada qrupu": ["e.g. X b (math group), Olympiad group", "напр. X b (группа по математике), Олимпиадная группа"],
  "məs. X e, XI peşə sinfi": ["e.g. X e, XI vocational class", "напр. X e, XI профессиональный класс"],
  "qrupun növü dəyişmir": ["the group type does not change", "тип группы не меняется"],
  "TOM ↔ adi dəyişir": ["TOM ↔ regular can be switched", "ТОМ ↔ обычный можно менять"],
  "Adi sinif": ["Regular class", "Обычный класс"],
  "Bölünmə qrupu (sinif daxilində)": ["Split group (within a class)", "Группа деления (внутри класса)"],
  "Tədris qrupu (müxtəlif siniflərdən)": ["Teaching group (from different classes)", "Учебная группа (из разных классов)"],
  "Ana sinif": ["Parent class", "Основной класс"],
  "Paralel fənn (sinfin digər yarısı)": ["Parallel subject (the other half of the class)", "Параллельный предмет (другая половина класса)"],
  "Biologiya – Şərqiyə müəllimə": ["Biology – Ms. Sharqiya", "Биология – учитель Шаркия"],
  "Hazırlıq məqsədi": ["Preparation goal", "Цель подготовки"],
  "— seçilməyib —": ["— not selected —", "— не выбрано —"],
  "UTİS sinfi": ["UTİS class", "Класс UTİS"],
  "Sinif rəqəmi": ["Grade number", "Номер класса"],
  "İmtahan tarixi": ["Exam date", "Дата экзамена"],
  "Tədris qrupu (olimpiada, hazırlıq, dərnək): yaratdıqdan sonra «Qoşul» ilə cədvəli, «Üzvlər» ilə müxtəlif siniflərdən şagirdləri seçin.": ["Teaching group (olympiad, preparation, club): after creating it, set the timetable with «Join» and choose students from different classes with «Members».", "Учебная группа (олимпиада, подготовка, кружок): после создания задайте расписание через «Присоединиться» и выберите учеников из разных классов через «Участники»."],
  "Fərdi hazırlıqda məktəb zəngi yoxdur: dərs günlərini və real vaxtlarını «Qoşul» pəncərəsində yazırsınız.": ["Private tutoring has no school bell: you enter the lesson days and real times in the «Join» window.", "В индивидуальной подготовке нет школьного звонка: дни и реальное время уроков вы указываете в окне «Присоединиться»."],
  "Bu sinfin öz zəngi var (məs. XI peşə 08:00)": ["This class has its own bell schedule (e.g. XI vocational 08:00)", "У этого класса свой звонок (напр. XI профессиональный 08:00)"],
  "Məktəbin ümumi zəngi işlənir.": ["The school's general bell schedule is used.", "Используется общий звонок школы."],
  "Rəsmi perspektiv plan (.docx)": ["Official long-term plan (.docx)", "Официальный перспективный план (.docx)"],
  "Yüklənib: {plan_lessons} dərs. Yenidən yükləmək jurnal qeydlərini saxlayır.": ["Uploaded: {plan_lessons} lessons. Uploading again keeps the journal entries.", "Загружено: {plan_lessons} уроков. Повторная загрузка сохраняет записи журнала."],
  "Plan yüklənməyib.": ["The plan has not been uploaded.", "План не загружен."],
  "Plan yükləndi: {lessons} dərs, KSQ {ksq}, BSQ {bsq}": ["Plan uploaded: {lessons} lessons, KSQ {ksq}, BSQ {bsq}", "План загружен: {lessons} уроков, КСО {ksq}, БСО {bsq}"],
