  "Rəhbər:": ["Homeroom teacher:", "Классный руководитель:"],
  ". Dəyişmək üçün adminə müraciət edin.": [". Contact the admin to change it.", ". Чтобы изменить, обратитесь к админу."],
  "Bu sinfin rəhbəri yoxdur.": ["This class has no homeroom teacher.", "У этого класса нет классного руководителя."],
  "Mən sinif rəhbəriyəm": ["I am the homeroom teacher", "Я классный руководитель"],
  "Sinif rəhbəri sinfin bütün fənləri üzrə dərs sayını, qiymətləri, müvəffəqiyyəti və davamiyyəti görür (başqa müəllimlərin jurnal qeydlərini yox).": ["The homeroom teacher sees the lesson count, grades, pass rate and attendance across all subjects of the class (not other teachers' journal entries).", "Классный руководитель видит число уроков, оценки, успеваемость и посещаемость по всем предметам класса (но не записи журнала других учителей)."],
  "dərs cədvəli": ["lesson timetable", "расписание уроков"],
