  "dərs · kursda": ["lessons · in the course", "уроков · в курсе"],
  "dərs yuvası": ["lesson slots", "уроков в расписании"],
  "Qoşulandan sonra «Cədvəl» → «Bölmələri seç» ilə lazım olan bölmələri seçə bilərsiniz.": ["After joining you can choose the sections you need with «Timetable» → «Choose sections».", "После присоединения нужные разделы можно выбрать через «Расписание» → «Выбрать разделы»."],
  "Qrupun məqsədi:": ["Goal of the group:", "Цель группы:"],
