  "Kurs müddəti (istəyə görə)": ["Course duration (optional)", "Срок курса (по желанию)"],
  "Bu qrupun cədvəli köhnə qaydada (dərs saatı ilə) yazılıb.": ["This group's timetable was written the old way (by lesson period).", "Расписание этой группы записано по-старому (по номеру урока)."],
  "Real dərs vaxtlarına keç": ["Switch to real lesson times", "Перейти на реальное время уроков"],
  "Dərs saatlarını işarələyin (0 – birinci dərsdən əvvəlki saat, məs. XI peşə 08:00):": ["Mark the lesson periods (0 – the period before the first lesson, e.g. XI vocational 08:00):", "Отметьте номера уроков (0 – час перед первым уроком, напр. XI профессиональный 08:00):"],
