  "Fərdi hazırlıqda məktəb zəngi yoxdur – hər dərsin gününü və real vaxtını yazın (məs. Ç.a. 17:00–18:30, Ş. 10:00–11:30).": ["Private tutoring has no school bell – enter the day and real time of each lesson (e.g. Tue 17:00–18:30, Sat 10:00–11:30).", "В индивидуальной подготовке нет школьного звонка – укажите день и реальное время каждого урока (напр. Вт 17:00–18:30, Сб 10:00–11:30)."],
