  "Oğlan": ["Boy", "Мальчик"],
  "Soyadı və adı yazın (ata adı da tövsiyə olunur).": ["Enter the surname and first name (the patronymic is recommended too).", "Введите фамилию и имя (отчество тоже желательно)."],
