  "Uşaq İD, pinkod və şəxsiyyət vəsiqəsi daxil edilmir. Eyni ad + doğum tarixi ikinci dəfə yaradılmır.": ["Child ID, PIN code and identity card are not entered. The same name + date of birth is not created twice.", "Детский ID, пин-код и удостоверение личности не вводятся. Один и тот же ФИО + дата рождения повторно не создаётся."],
  "{name} – üzvlər": ["{name} – members", "{name} – участники"],
  "Seçilib:": ["Selected:", "Выбрано:"],
  "Sinfi seçin və şagirdləri işarələyin – bir neçə sinifdən yığmaq olar. Şagird öz sinfində qalır, qrupa yalnız üzv olur.": ["Choose a class and tick the students – you can gather from several classes. The student stays in their own class and only becomes a member of the group.", "Выберите класс и отметьте учеников – можно собирать из нескольких классов. Ученик остаётся в своём классе и лишь становится участником группы."],
  "— sinif seçin —": ["— select a class —", "— выберите класс —"],
  "Sinifdə şagird yoxdur.": ["There are no students in the class.", "В классе нет учеников."],
  "Qrupun üzvləri (": ["Group members (", "Участники группы ("],
  "Çıxar": ["Remove", "Убрать"],
  "Hələ üzv yoxdur.": ["No members yet.", "Участников пока нет."],
  "{name} – bölünmə yarat": ["{name} – create a split", "{name} – создать деление"],
  "Qrup yaradıldı – indi «Qoşul» ilə cədvəli, «Bölünmə» ilə şagirdləri seçin": ["The group was created – now set the timetable with «Join» and choose students with «Split»", "Группа создана – теперь задайте расписание через «Присоединиться» и выберите учеников через «Деление»"],
  "Sinif bəzi saatlarda iki qrupa bölünür: bir qrup sizin fənninizə, digəri paralel fənnə gedir. Şagirdləri sonra özünüz seçəcəksiniz.": ["The class is split into two groups at some hours: one group goes to your subject, the other to the parallel subject. You will choose the students afterwards.", "В некоторые часы класс делится на две группы: одна идёт на ваш предмет, другая – на параллельный. Учеников вы выберете позже."],
  "Sizin qrupun fənni": ["Subject of your group", "Предмет вашей группы"],
  "Paralel fənn (və müəllimi)": ["Parallel subject (and its teacher)", "Параллельный предмет (и его учитель)"],
  "Siyahıya qayıt": ["Back to the list", "Назад к списку"],
  "IX buraxılış ballarını redaktə et": ["Edit Grade IX graduation scores", "Редактировать выпускные баллы IX класса"],
  "Şagirdin ID və PIN-ini dəyişmək: sinfi seçin → şagirdi açın → «Giriş məlumatları».": ["To change a student's ID and PIN: choose the class → open the student → «Login details».", "Чтобы изменить ID и PIN ученика: выберите класс → откройте ученика → «Данные для входа»."],
  "· IX riyaziyyat": ["· Grade IX math", "· математика IX"],
  "Yeni PIN": ["New PIN", "Новый PIN"],
  "Giriş məlumatı": ["Login details", "Данные для входа"],
  "PIN": ["PIN", "PIN"],
  "PIN yalnız indi göstərilir – yazın və şagirdə verin. Şagird PIN-i sonra özü dəyişə bilər.": ["The PIN is shown only now – write it down and give it to the student. The student can change the PIN later.", "PIN показывается только сейчас – запишите и передайте ученику. Позже ученик сможет сам сменить PIN."],
  "Siniflərinizdə şagird yoxdur.": ["There are no students in your classes.", "В ваших классах нет учеников."],
  "{length} sinif, {x2} şagird": ["{length} classes, {x2} students", "Классов: {length}, учеников: {x2}"],
  "{new_pins} şagirdə yeni PIN verildi": ["new PINs were issued to {new_pins} students", "новые PIN выданы ученикам: {new_pins}"],
  "Giriş vərəqələri – bütün siniflər (ID + PIN)": ["Login slips – all classes (ID + PIN)", "Листки входа – все классы (ID + PIN)"],
  "şagirdin ilkin PIN-i yoxdur (şagird dəyişib və ya köhnə qeyddir).": ["students have no initial PIN (the student changed it or it is an old record).", "у учеников нет первоначального PIN (ученик сменил его или это старая запись)."],
