  "IX sinif buraxılış imtahanı balları (0–100). Boş – bal yoxdur. Riyaziyyat balı şagirdin ilkin səviyyəsini müəyyən edir.": ["Grade IX graduation exam scores (0–100). Empty – no score. The math score determines the student's initial level.", "Баллы выпускного экзамена IX класса (0–100). Пусто – балла нет. Балл по математике определяет первоначальный уровень ученика."],
  "şagird dəyişib": ["the student changed it", "ученик сменил"],
  "Giriş məlumatları": ["Login details", "Данные для входа"],
  "Giriş kodu (ID)": ["Login code (ID)", "Код входа (ID)"],
  "Təsadüfi": ["Random", "Случайный"],
  "Yeni PIN:": ["New PIN:", "Новый PIN:"],
  "– giriş vərəqəsində də çap olunacaq. Şagirdin köhnə PIN-i artıq işləmir.": ["– it will also be printed on the login slip. The student's old PIN no longer works.", "– он также будет напечатан на листке входа. Старый PIN ученика больше не действует."],
  "Kod dəyişəndə şagird yeni kodla daxil olur (köhnə kod işləmir).": ["When the code changes the student logs in with the new code (the old one stops working).", "При смене кода ученик входит с новым кодом (старый не действует)."],
