  "Uşaq İD, pinkod və şəxsiyyət vəsiqəsi daxil edilmir və saxlanmır.": ["Child ID, PIN code and identity card are not entered or stored.", "Детский ID, пин-код и удостоверение личности не вводятся и не сохраняются."],
  "Məktəbdən getdi – passiv et": ["Left the school – make inactive", "Ушёл из школы – сделать неактивным"],
  "UTİS siyahısından şagird idxalı (admin)": ["Import students from the UTİS list (admin)", "Импорт учеников из списка UTİS (админ)"],
  "Siniflər «UTİS sinfi» sahəsinə görə uyğunlaşdırılır (məs. X e = 10 e). Uşaq İD, şəxsiyyət vəsiqəsi, pinkod saxlanmır; mövcud şagirdlər təkrarlanmır.": ["Classes are matched by the «UTİS class» field (e.g. X e = 10 e). Child ID, identity card and PIN code are not stored; existing students are not duplicated.", "Классы сопоставляются по полю «Класс UTİS» (напр. X e = 10 e). Детский ID, удостоверение личности и пин-код не сохраняются; существующие ученики не дублируются."],
  "UTİS faylı (.xlsx və ya .pdf)": ["UTİS file (.xlsx or .pdf)", "Файл UTİS (.xlsx или .pdf)"],
