  "· əlavə:": ["· added:", "· добавлено:"],
  "balı olmayan: {without_scores}": ["without a score: {without_scores}", "без балла: {without_scores}"],
  "Giriş kodları və PIN-lər (CSV)": ["Login codes and PINs (CSV)", "Коды входа и PIN (CSV)"],
  "PIN-lər yalnız indi göstərilir – faylı yükləyin, çap edib paylayın.": ["PINs are shown only now – download the file, print and distribute.", "PIN показываются только сейчас – скачайте файл, распечатайте и раздайте."],
  "Şagird siyahılardan, jurnaldan və portaldan çıxır; qiymətləri və tarixçəsi silinmir. «Arxiv» bölməsindən geri qaytarmaq və ya həmişəlik silmək olar.": ["The student is removed from lists, the journal and the portal; their grades and history are not deleted. They can be restored or deleted permanently from the «Archive» section.", "Ученик исчезает из списков, журнала и портала; его оценки и история не удаляются. Из раздела «Архив» его можно вернуть или удалить навсегда."],
