  "Eyni": ["The same", "Те же"],
  "sualla yeni test yaradılır. Köhnə testin nəticələri yerində qalır; şagirdlər yenisini təzədən həll edir.": ["questions create a new test. The old test's results stay in place; students solve the new one from scratch.", "вопросы создают новый тест. Результаты старого теста остаются на месте; ученики решают новый заново."],
  "(həmin sinif)": ["(that class)", "(этот класс)"],
  "Bağlanır": ["Closes", "Закрывается"],
  "Testi link kimi göndər": ["Send the test as a link", "Отправить тест ссылкой"],
  "Şagird linki açır → giriş kodu və PIN ilə daxil olur (və ya qeydiyyat linki ilə qeydiyyatdan keçir) → birbaşa bu testə düşür. Test yalnız bu sinfin/qrupun (seçilmiş) şagirdlərinə açılır.": ["The student opens the link → logs in with the login code and PIN (or registers via the registration link) → goes straight to this test. The test is open only to the (selected) students of this class/group.", "Ученик открывает ссылку → входит по коду входа и PIN (или регистрируется по ссылке регистрации) → сразу попадает на этот тест. Тест открыт только (выбранным) ученикам этого класса/группы."],
