  "Qiymət: düzgün / sual → faiz → qiymət. Həmin dərsdə olmayan şagird ötürülür; təkrar köçürmə köhnəni yeniləyir.": ["Grade: correct / questions → percent → grade. A student who was not in that lesson is skipped; copying again updates the old one.", "Оценка: верных / вопросов → проценты → оценка. Ученик, которого не было на этом уроке, пропускается; повторный перенос обновляет прежнюю оценку."],
