  "Bu dövrdə mövzu testi nəticəsi yoxdur – Perspektiv plan → mövzu → «Test təyin et».": ["There are no topic test results in this period – Long-term plan → topic → «Assign a test».", "За этот период результатов тестов по темам нет – Перспективный план → тема → «Назначить тест»."],
