  "Mövzu testləri formativ jurnala düşür.": ["Topic tests go to the formative journal.", "Тесты по темам попадают в формативный журнал."],
  "Sınaqlar formativ qiymətə təsir etmir; faiz cərimə ilə.": ["Mock exams do not affect the formative grade; the percentage includes the penalty.", "Пробные экзамены не влияют на формативную оценку; процент – с учётом штрафа."],
  "Yer – verilən testlərin ən azı 40 %-ni yazanlara (az yazan sonda, yersiz). Mövzu testi və sınaq reytinqi qarışmır. Şagirdə toxunun – profil açılır.": ["Rank – for those who wrote at least 40% of the given tests (low participants at the end, unranked). Topic-test and mock-exam rankings are not mixed. Tap a student – the profile opens.", "Место – тем, кто написал не менее 40% выданных тестов (пишущие мало – в конце, без места). Рейтинги тестов по темам и пробных экзаменов не смешиваются. Нажмите на ученика – откроется профиль."],
  "Ən çox irəliləyənlər": ["Most improved", "Больше всего улучшили результат"],
  "Diqqət tələb edənlər": ["Need attention", "Требуют внимания"],
