  "test)": ["tests)", "тестов)"],
  "Hər test eyni suallarla yalnız onu yazmayan seçilmiş şagirdlərə yeni vaxtla göndərilir. Şagird portalında bildiriş çıxır. Yazandan sonra nəticə əsas testə yazılır və şagird bu siyahıdan çıxır.": ["Each test is sent with the same questions and a new time only to the selected students who did not write it. A notification appears in the student portal. After writing, the result is recorded in the main test and the student leaves this list.", "Каждый тест отправляется с теми же вопросами и новым временем только выбранным ученикам, не писавшим его. В портале ученика появится уведомление. После написания результат записывается в основной тест, и ученик исчезает из этого списка."],
  "Həll müddəti, dəq": ["Solving time, min", "Время решения, мин"],
  "Yalnız sonuncu yazmadığı test": ["Only the last test they did not write", "Только последний тест, который не писал(а)"],
