  "üzrə": ["for", "по"],
  "Mövzu testləri və sınaqların rəqəmlərinə əsasən güclü/zəif tərəflər, ehtimal olunan səbəblər və 2–4 həftəlik tövsiyələr. Şagird adları provayderə göndərilmir (kodla). Tənzimləmələr → «Süni intellekt»də öz açarınız lazımdır.": ["Strengths/weaknesses, likely causes and 2–4 week recommendations based on the topic test and mock exam figures. Student names are not sent to the provider (only codes). You need your own key in Settings → «Artificial intelligence».", "Сильные/слабые стороны, вероятные причины и рекомендации на 2–4 недели на основе цифр по тестам тем и пробным экзаменам. Имена учеников провайдеру не отправляются (только коды). Нужен свой ключ в Настройки → «Искусственный интеллект»."],
  "İnkişaf ehtiyacı": ["Development need", "Потребность в развитии"],
  "Ehtimal olunan səbəblər": ["Likely causes", "Вероятные причины"],
