  "Fənn müəlliminin jurnalı olan dərs kilidlidir (🔒) – əsas mənbə jurnaldır.": ["A lesson that has the subject teacher's journal entry is locked (🔒) – the journal is the main source.", "Урок, по которому есть запись в журнале предметника, заблокирован (🔒) – основной источник – журнал."],
