  "Bütün gün": ["All day", "Весь день"],
  "Üzrlü səbəb": ["Reason for excuse", "Причина уважительного отсутствия"],
  "səbəb —": ["reason —", "причина —"],
  "fənn müəlliminin jurnalı": ["subject teacher's journal", "журнал предметника"],
  "basın: V → Q → Ü → G → boş": ["press: P → A → E → L → empty", "нажмите: Б → Н → У → О → пусто"],
  "Bütün gün qayıb": ["Absent all day", "Отсутствовал весь день"],
  "Bütün gün üzrlü": ["Excused all day", "Весь день по уважительной"],
  "Bütün gün var": ["Present all day", "Присутствовал весь день"],
  "Xanaya basın: V (var) → Q (qayıb) → Ü (üzrlü) → G (gecikib) → boş. Üzrlü olanda səbəbi seçin. «Bütün gün» – şagird həmin gün heç bir dərsdə olmayıbsa (və ya hamısında olub).": ["Click a cell: P (present) → A (absent) → E (excused) → L (late) → empty. When excused, choose the reason. «All day» – if the student was in none (or all) of that day's lessons.", "Нажимайте на ячейку: Б (был) → Н (не был) → У (уважительно) → О (опоздал) → пусто. При «уважительно» выберите причину. «Весь день» – если ученик не был ни на одном (или был на всех) уроках в этот день."],
  "Bu saat: boşlar – hamı var": ["This period: empty – everyone present", "Этот урок: пусто – все присутствуют"],
