  "Fənn jurnalı:": ["Subject journal:", "Журнал предмета:"],
  "Davamiyyət: {full_name}": ["Attendance: {full_name}", "Посещаемость: {full_name}"],
  "səbəb seçin": ["choose a reason", "выберите причину"],
  "Bütün gün…": ["All day…", "Весь день…"],
  "Yadda saxla (": ["Save (", "Сохранить ("],
