  "Növbəti ay": ["Next month", "Следующий месяц"],
  "Bu ayda (bu günə qədər) dərs günü yoxdur.": ["There are no lesson days this month (so far).", "В этом месяце (до сегодняшнего дня) учебных дней нет."],
