  "Əvvəlcə sinifləri seçin – siyahı sinfə görə süzülür (11-ci sinfə yalnız 11-in sınaqları).": ["Choose the classes first – the list is filtered by grade (only grade 11 mock exams for grade 11).", "Сначала выберите классы – список фильтруется по классу (для 11 класса – только пробные 11 класса)."],
