  "sınaq seçilmiş siniflərin sinfinə uyğun deyil – bilərəkdən verirəm (təsdiq)": ["the mock exam does not match the grade of the selected classes – I am giving it on purpose (confirm)", "пробный экзамен не соответствует классу выбранных классов – выдаю намеренно (подтверждаю)"],
  "Artıq verilmiş sınaq sinfə ikinci dəfə göndərilmir; avtomatik əlavə olunanlar yalnız sinfin öz sınaqlarıdır.": ["A mock exam already given is not sent to a class a second time; automatically added ones are only the class's own mock exams.", "Уже выданный пробный экзамен классу повторно не отправляется; автоматически добавляются только пробные экзамены самого класса."],
