  "Seriyada iştirak, %": ["Series participation, %", "Участие в серии, %"],
  "Sınağın tarixi": ["Date of the mock exam", "Дата пробного экзамена"],
  "Əyani və onlayn məşğələ qrupları – öz planı, davamiyyət, statistika (jurnala qiymət yazmır). Qrupa istənilən sinfinizdən şagird əlavə edə və çıxara bilərsiniz.": ["In-person and online activity groups – own plan, attendance, statistics (no grades are written to the journal). You can add students to a group from any of your classes and remove them.", "Очные и онлайн-группы занятий – свой план, посещаемость, статистика (оценки в журнал не ставятся). В группу можно добавлять и убирать учеников из любого вашего класса."],
