  "Kurs yaradıldı – {sessions} məşğələ planlaşdırıldı": ["The course was created – {sessions} sessions planned", "Курс создан – запланировано занятий: {sessions}"],
  "Diqqət: məktəb cədvəli ilə toqquşma var – kursda baxın": ["Attention: there is a clash with the school timetable – check it in the course", "Внимание: есть конфликт со школьным расписанием – посмотрите в курсе"],
  "Yeni əlavə məşğələ kursu": ["New extra activity course", "Новый курс дополнительных занятий"],
