  "Səviyyə qrupu": ["Level group", "Группа по уровню"],
  "Səviyyə qrupları Jurnal → «Səviyyə qrupları»nda təyin olunur. Şagird öz səviyyəsini görmür – yalnız kursu görür.": ["Level groups are set in Journal → «Level groups». Students do not see their level – only the course.", "Группы по уровню задаются в Журнал → «Группы по уровню». Ученик не видит свой уровень – только курс."],
  "https://meet… (onlayn)": ["https://meet… (online)", "https://meet… (онлайн)"],
  "+ gün": ["+ day", "+ день"],
  "Tarixlər bu cədvəldən avtomatik qurulur, tətil və bayram günləri çıxılır. Qarışıq formatda keçidi olan gün onlayn sayılır.": ["Dates are built from this table automatically; holidays and breaks are excluded. In mixed format a day with a link counts as online.", "Даты формируются из этой таблицы автоматически, праздники и каникулы исключаются. В смешанном формате день со ссылкой считается онлайн."],
  "əlavə oluna bilər": ["can be added", "можно добавить"],
  "Bu səviyyədə əlavə ediləsi şagird yoxdur.": ["There are no students to add at this level.", "На этом уровне некого добавлять."],
  "Bu sinfin bütün şagirdləri artıq qrupdadır.": ["All students of this class are already in the group.", "Все ученики этого класса уже в группе."],
  "Bütün «{x1}» seç": ["Select all «{x1}»", "Выбрать всех «{x1}»"],
  "Qrupa əlavə et (": ["Add to the group (", "Добавить в группу ("],
  "Yalnız seçdiyiniz şagirdlər qoşulur – sinfin qalanı yox. Səviyyə (Zəif / Orta / Güclü) – Jurnal → «Səviyyə qrupları»ndan; zəif və güclü qrupları ayrıca məşğələ qrupu kimi saxlamaq üçün hər qrupa öz səviyyəsini əlavə edin.": ["Only the students you select are added – not the rest of the class. Level (Weak / Average / Strong) – from Journal → «Level groups»; to keep weak and strong groups as separate activity groups, add each group's own level.", "Добавляются только выбранные вами ученики – не остальной класс. Уровень (Слабый / Средний / Сильный) – из Журнал → «Группы по уровню»; чтобы вести слабую и сильную группы как отдельные группы занятий, добавьте каждой группе её уровень."],
  "✕ çıxar": ["✕ remove", "✕ убрать"],
  "Çıxarılan şagirdin keçmiş davamiyyəti qalır; növbəti məşğələləri artıq görmür.": ["The removed student's past attendance is kept; they no longer see the upcoming sessions.", "Прошлая посещаемость убранного ученика сохраняется; следующих занятий он больше не видит."],
  "Qrupdan çıxarıldı": ["Removed from the group", "Убран из группы"],
  "Qrupa əlavə olundu": ["Added to the group", "Добавлен в группу"],
