  "5–8 sual məşğələnin effektini ölçür. Yalnız kursun şagirdləri görür; nəticə jurnala yazılmır – statistikaya düşür.": ["5–8 questions measure the effect of the session. Only the course students see it; the result is not written to the journal – it goes to the statistics.", "5–8 вопросов измеряют эффективность занятия. Видят только ученики курса; результат в журнал не записывается – попадает в статистику."],
