  "Kursdan əvvəl və sonra test/sınaq nəticəsi yığıldıqca burada görünəcək.": ["As test/mock-exam results before and after the course accumulate, they will appear here.", "По мере накопления результатов тестов/пробных до и после курса они появятся здесь."],
