  "bal. Bal sualın növü (açıq ×1,5) və çətinliyinə (orta ×1,5, çətin ×2) görə; «avto» – şagird nəticələrinin statistikası, yoxdursa növ.": ["points. The score depends on the question type (open ×1.5) and difficulty (medium ×1.5, hard ×2); «auto» – based on the statistics of student results, otherwise on the question type.", "баллов. Балл зависит от типа вопроса (открытый ×1,5) и сложности (средний ×1,5, сложный ×2); «авто» – по статистике результатов учеников, иначе по типу вопроса."],
