  "Siz artıq daxil olmusunuz. Başqa cihazdan girmək üçün kodu və PIN-i yazın və ya şəklini çəkin – bir daha göstərilməyəcək.": ["You are already signed in. To sign in from another device, write down the code and PIN or take a photo of them – they will not be shown again.", "Вы уже вошли в систему. Чтобы войти с другого устройства, запишите код и PIN или сфотографируйте их – повторно они показаны не будут."],
  "Soyadınız və adınız": ["Your last name and first name", "Ваши фамилия и имя"],
