  "Siz artıq qeydiyyatdasınız – giriş kodunuzu və PIN-i müəlliminizdən soruşun": ["You are already registered – ask your teacher for your login code and PIN", "Вы уже зарегистрированы – спросите у учителя свой код для входа и PIN"],
