  "Çap olunub, nəticəsi olmayan imtahan: {n}": ["Printed, no results yet: {n} exam(s)", "Распечатано, результатов нет: {n}"],
  "Kartın QR-ı imtahanı və şagirdi özü tapır – sinif və imtahan seçmək lazım deyil.": ["The card's QR finds the exam and student by itself – no need to pick a class or exam.", "QR-код карточки сам находит экзамен и ученика – выбирать класс и экзамен не нужно."],
  "Şəkil çək": ["Take photo", "Сделать снимок"],
  "Fayl yüklə": ["Upload file", "Загрузить файл"],
  "QR oxunmadı: {n} fayl – şagirdi və imtahanı özünüz seçin": ["QR not read in {n} file(s) – pick the student and exam yourself", "QR не прочитан в файлах: {n} – выберите ученика и экзамен вручную"],
  "Şagird və imtahanı seçin": ["Pick student and exam", "Выберите ученика и экзамен"],
  "Qəbul et": ["Accept", "Принять"],
  "Son 7 gün": ["Last 7 days", "Последние 7 дней"],
  "Yazılı iş üçün sinif seçin": ["Pick a class for the written work", "Выберите класс для письменной работы"],
  "Hazır testi və ya sınağı kağızda keçirin (hamıya eyni vərəq) və ya bank fayllarından sərbəst yazılı iş düzəldin. Hər şagirdə QR-lı cavab vərəqi çap olunur, sonra istənilən səhifədən «📷 Skan» ilə oxunur.": ["Run a ready test or mock exam on paper (same sheet for all) or build a free written work from bank files. Each student gets a printed answer sheet with a QR code, then it is read from any page with «📷 Scan».", "Проведите готовый тест или пробный экзамен на бумаге (один бланк для всех) или составьте свободную письменную работу из файлов банка. Каждому ученику печатается бланк с QR-кодом, затем он считывается с любой страницы кнопкой «📷 Скан»."],
  "Yazılı iş yarat": ["Create written work", "Создать письменную работу"],
  "Hələ yazılı iş yoxdur": ["No written work yet", "Письменных работ пока нет"],
  "Sərbəst yazılı iş": ["Free written work", "Свободная письменная работа"],
  "Skan: {a}/{b}": ["Scanned: {a}/{b}", "Отсканировано: {a}/{b}"],
  "Vərəqləri çap et": ["Print sheets", "Печать бланков"],
  "Jurnala yaz": ["Write to journal", "Записать в журнал"],
  "Yazılı iş silinsin?": ["Delete this written work?", "Удалить письменную работу?"],
  "Yenə də silinsin?": ["Delete anyway?", "Всё равно удалить?"],
  "Kağız": ["Paper", "Бумага"],
  "Kağız və onlayn bal fərqlidir": ["Paper and online scores differ", "Баллы на бумаге и онлайн различаются"],
  "Yazılı iş hazırdır – vərəqləri çap edin": ["Written work is ready – print the sheets", "Письменная работа готова – распечатайте бланки"],
  "Hazır test / sınaq": ["Ready test / mock exam", "Готовый тест / пробный экзамен"],
